fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo and switch to the Routines app. Then perform these sub-actions IN ORDER, and as you complete each set \"checkpointReached\" to the exact checkpoint name shown: (1) routine-run-history — if at least one routine card is present, click its run-history icon (a timeline icon among the card's action buttons) to open the History view and confirm it renders a header showing 'History' for that routine and EITHER a list of run rows (each with a status chip and a start time) OR a 'No Runs Yet' empty state (if there are no routine cards at all, that is acceptable — report the list is empty); you do NOT need to open any linked run record; (2) routines-search-filter — return to the routines list, use the 'Search routines...' box to type a query and open the 'Filters' popover (funnel icon) to pick a Status other than 'All statuses' (e.g. Active or Paused), and confirm the card list RESPONDS — the visible cards narrow to matches, the X-of-Y count badge updates, OR a 'No Matching Routines' empty state appears — then clear the filters and confirm the unfiltered list returns. Keep going until both sub-actions are done. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "routine-run-history",
      "instruction": "open a routine's run-history view",
      "visualCriteria": [
        "Opening a routine's history shows a History view for that routine with either run rows (status chips + timestamps) OR a 'No Runs Yet' empty state — or the routines list is legitimately empty"
      ]
    },
    {
      "name": "routines-search-filter",
      "instruction": "search + status filter the routine card list",
      "visualCriteria": [
        "Typing in the 'Search routines...' box and/or choosing a Status in the Filters popover changes the visible cards, updates the count badge, or shows a 'No Matching Routines' empty state, and clearing the filters restores the unfiltered list"
      ]
    }
  ]
}
